import java.util.HashMap;
import java.util.Map;

/**
 * TASK: Complete ColorToken, a static factory that CACHES one instance per
 * name so that asking twice hands back the very same object.
 *
 * The constructor is already private: callers must go through of(...).
 * The cache map is static, so it is shared by the whole program, not stored
 * per instance.
 *
 * Rules:
 *   - of(name) normalises the key with trim() and toUpperCase()
 *   - of(null) and of a blank name return null and cache nothing
 *   - the same normalised key always returns the SAME object (==), a
 *     different key returns a different object
 *   - name() reports the normalised upper-case name
 *   - cachedCount() reports how many tokens the cache holds
 *   - clearCache() empties the cache, so the next of("red") builds a fresh
 *     object
 *
 * Example: ColorToken.of("  red ") == ColorToken.of("RED") is true and both
 *   have name() "RED".
 */
public class ColorToken {

    private static final Map<String, ColorToken> CACHE = new HashMap<>();

    private final String name;

    private ColorToken(String name) {
        this.name = name;
    }

    public static ColorToken of(String name) {
        if (name == null) {
            return null;
        }
        String key = name.trim().toUpperCase();
        if (key.isEmpty()) {
            return null;
        }
        ColorToken cached = CACHE.get(key);
        if (cached == null) {
            cached = new ColorToken(key);
            CACHE.put(key, cached);
        }
        return cached;
    }

    public String name() {
        return name;
    }

    public static int cachedCount() {
        return CACHE.size();
    }

    public static void clearCache() {
        CACHE.clear();
    }
}
